import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long x = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long total = 0;
        for (int i = 0; i < n; i++) total += a[i];
        long target = total - x;
        if (target < 0) {
            System.out.println(-1);
        } else if (target == 0) {
            System.out.println(n);
        } else {
            Map<Long, Integer> first = new HashMap<>();
            first.put(0L, -1);
            long cur = 0;
            int longest = -1;
            for (int i = 0; i < n; i++) {
                cur += a[i];
                Integer start = first.get(cur - target);
                if (start != null) longest = Math.max(longest, i - start);
                first.putIfAbsent(cur, i);
            }
            System.out.println(longest >= 0 ? n - longest : -1);
        }
    }
}
